//! Section 9, instrument three, for the forms EvoMIR 0.11 to 0.14 opened.
//!
//! "The assembled program is run on the host and its output compared with the
//! reference compiler's build of the same C source (the layout oracle's GCC-14
//! on the sealed container for Linux; the host toolchain for Darwin, recorded
//! by version)."
//!
//! The Day 5 and Day 7 corpora are generated by their own authorities and hold
//! no unit that reaches these rows, so the programs below are written here: one
//! per form the revision opened, each a whole C program whose exit status is
//! the measurement. A program may name a second translation unit, which the
//! reference compiler builds on both sides; that is how a call to a symbol this
//! module does not define is linked (Section 8, revision 0.11).

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};
use std::process::Command;

use evocc_evoir::parse_section9_module;
use evocc_mir::{compile_module_for, Driver, NativeStop, Target, Toolchain};

/// The runtime and image the build-environment contract seals.
const CONTAINER_BIN: &str = "/usr/local/bin/container";
const IMAGE: &str = "evo-flight-lab:sealed";

/// One program: the unit EvoCC compiles, and the unit the reference compiler
/// supplies on both sides.
struct Program {
    name: &'static str,
    unit: &'static str,
    /// The unit to use on Darwin, where a C symbol carries the `_` prefix and
    /// a file-scope `asm` that defines one must spell it.
    darwin: Option<&'static str>,
    other: Option<&'static str>,
}

impl Program {
    const fn source(&self, target: Target) -> &'static str {
        match (target, self.darwin) {
            (Target::Darwin, Some(unit)) => unit,
            _ => self.unit,
        }
    }
}

/// A call to an undefined function and a read of an undefined object, linked
/// against a reference-compiled object (EvoMIR Section 8, revision 0.11).
const EXTERNAL_UNIT: &str = r#"extern int helper(int x);
extern int table_value;
extern unsigned char narrow(unsigned char c);

int main(void) {
    int total = helper(7) + table_value;
    total += (int)narrow((unsigned char)200);
    return total & 0xff;
}
"#;

const EXTERNAL_OTHER: &str = r#"int table_value = 11;
int helper(int x) { return x * 3; }
unsigned char narrow(unsigned char c) { return (unsigned char)(c + 1u); }
"#;

/// A static table of pointers and function pointers with addends, and the two
/// pointer-integer conversions (EvoMIR revision 0.12).
const RELOCATION_UNIT: &str = r#"static int table[4] = {10, 20, 30, 40};
static int twice(int x) { return x + x; }
static int thrice(int x) { return x * 3; }

struct pair { int a; long b; };
static struct pair sv = {1, 2};

static int *pointers[3] = { &table[0], &table[2], table + 3 };
static int (*funcs[2])(int) = { twice, thrice };
static long *inner = &sv.b;

int main(void) {
    int total = *pointers[0] + *pointers[1] + *pointers[2];
    total += funcs[0](5) + funcs[1](5);
    total += (int)*inner;
    unsigned long address = (unsigned long)(void *)&table[1];
    int *back = (int *)address;
    total += *back;
    return total & 0xff;
}
"#;

/// A file-scope `asm` that defines a symbol the C code reads (EvoMIR Section
/// 8, "Module assembly", revision 0.14).
const MODULE_ASSEMBLY_UNIT: &str = r#"__asm__(".globl module_value\n"
        ".data\n"
        ".p2align 2\n"
        "module_value: .long 41\n"
        ".text\n");

extern int module_value;

int main(void) { return module_value + 1; }
"#;

const MODULE_ASSEMBLY_DARWIN: &str = r#"__asm__(".globl _module_value\n"
        ".data\n"
        ".p2align 2\n"
        "_module_value: .long 41\n"
        ".text\n");

extern int module_value;

int main(void) { return module_value + 1; }
"#;

const PROGRAMS: &[Program] = &[
    Program {
        name: "external-symbols",
        unit: EXTERNAL_UNIT,
        darwin: None,
        other: Some(EXTERNAL_OTHER),
    },
    Program {
        name: "static-relocations",
        unit: RELOCATION_UNIT,
        darwin: None,
        other: None,
    },
    Program {
        name: "module-assembly",
        unit: MODULE_ASSEMBLY_UNIT,
        darwin: Some(MODULE_ASSEMBLY_DARWIN),
        other: None,
    },
];

fn workspace() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .and_then(Path::parent)
        .expect("the crate lives two directories below the workspace root")
        .to_path_buf()
}

/// Whether the sealed image is present and its runtime answers.
fn container() -> Result<String, String> {
    if !Path::new(CONTAINER_BIN).exists() {
        return Err(format!("{CONTAINER_BIN} is absent"));
    }
    let listed = Command::new(CONTAINER_BIN)
        .args(["image", "list"])
        .output()
        .map_err(|error| format!("{CONTAINER_BIN}: {error}"))?;
    if !listed.status.success() {
        return Err(format!(
            "the container runtime is not started: {}",
            String::from_utf8_lossy(&listed.stderr).trim()
        ));
    }
    if !String::from_utf8_lossy(&listed.stdout).contains("evo-flight-lab") {
        return Err(format!("{IMAGE} is not present"));
    }
    Ok(IMAGE.to_owned())
}

/// Write one program's sources into `directory` and return the unit's path.
fn materialize(directory: &Path, program: &Program, target: Target) -> PathBuf {
    let unit = directory.join(format!("{}.c", program.name));
    std::fs::write(&unit, program.source(target)).expect("the unit");
    if let Some(other) = program.other {
        std::fs::write(directory.join(format!("{}-other.c", program.name)), other)
            .expect("the second unit");
    }
    unit
}

/// The assembly EvoCC emits for one program's own unit.
fn assembly(driver: &Driver, target: Target, unit: &Path) -> Result<String, String> {
    let evoir = driver.emit_evoir(unit, false)?;
    let module = parse_section9_module(evoir.as_bytes()).map_err(|error| format!("E0000 {error}"))?;
    compile_module_for(target, &module, &|_| true).map_err(|stop: NativeStop| {
        format!("stopped at {}: {}", stop.component(), stop.detail())
    })
}

struct Row {
    programs: usize,
    refused: BTreeMap<String, usize>,
    compiled: usize,
    ran: usize,
    agreeing: usize,
    disagreements: Vec<(String, u8, u8)>,
}

impl Row {
    fn new() -> Self {
        Self {
            programs: PROGRAMS.len(),
            refused: BTreeMap::new(),
            compiled: 0,
            ran: 0,
            agreeing: 0,
            disagreements: Vec::new(),
        }
    }

    fn report(&self, lane: &str) {
        println!("lane={lane}");
        println!("programs={}", self.programs);
        println!(
            "refused={}",
            self.refused
                .iter()
                .map(|(reason, count)| format!("{reason}:{count}"))
                .collect::<Vec<_>>()
                .join(",")
        );
        println!("compiled={}", self.compiled);
        println!("ran={}", self.ran);
        println!("agreeing={}", self.agreeing);
        for (name, theirs, mine) in &self.disagreements {
            println!("disagreed={name} reference={theirs} evocc={mine}");
        }
    }

    fn settle(self) {
        if let Some((name, theirs, mine)) = self.disagreements.first() {
            panic!("{name}: the reference said {theirs}, EvoCC said {mine}");
        }
        assert_eq!(
            self.ran, self.programs,
            "every program of this corpus must reach a run: {:?}",
            self.refused
        );
        assert_eq!(self.agreeing, self.ran);
    }
}

/// Run one command and answer its exit status modulo 256.
fn status_of(program: &Path) -> Result<u8, String> {
    let run = Command::new(program)
        .output()
        .map_err(|error| error.to_string())?;
    let code = run
        .status
        .code()
        .ok_or_else(|| "the program did not exit normally".to_owned())?;
    u8::try_from(code & 0xff).map_err(|error| error.to_string())
}

/// The Darwin lane: the host clang assembles, links and runs both sides.
#[test]
fn the_frontier_corpus_agrees_with_the_host_compiler() {
    let Ok(toolchain) = Toolchain::locate() else {
        println!("skipped=the host toolchain is absent");
        return;
    };
    let driver = match Driver::locate() {
        Ok(driver) => driver,
        Err(reason) => {
            println!("skipped={reason}");
            return;
        }
    };
    println!("oracle={}", toolchain.version());

    let work = std::env::temp_dir().join(format!("evocc-frontier-darwin-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&work);
    std::fs::create_dir_all(&work).expect("a working directory");

    let mut row = Row::new();
    for program in PROGRAMS {
        let unit = materialize(&work, program, Target::Darwin);
        let text = match assembly(&driver, Target::Darwin, &unit) {
            Ok(text) => text,
            Err(reason) => {
                *row.refused.entry(reason).or_default() += 1;
                continue;
            }
        };
        row.compiled += 1;
        let source = work.join(format!("{}.s", program.name));
        std::fs::write(&source, &text).expect("the emitted text");

        let mine = work.join(format!("{}.mine", program.name));
        let mut link = Command::new("clang");
        link.arg("-o").arg(&mine).arg(&source);
        if program.other.is_some() {
            link.arg(work.join(format!("{}-other.c", program.name)));
        }
        let built = link.output().expect("run the host linker");
        if !built.status.success() {
            *row.refused
                .entry(format!(
                    "link: {}",
                    String::from_utf8_lossy(&built.stderr).trim()
                ))
                .or_default() += 1;
            continue;
        }
        let observed = match status_of(&mine) {
            Ok(status) => status,
            Err(reason) => {
                *row.refused.entry(format!("run: {reason}")).or_default() += 1;
                continue;
            }
        };
        row.ran += 1;

        let theirs = work.join(format!("{}.theirs", program.name));
        let mut reference = Command::new("clang");
        reference
            .arg("-std=c11")
            .arg("-O0")
            .arg("-o")
            .arg(&theirs)
            .arg(&unit);
        if program.other.is_some() {
            reference.arg(work.join(format!("{}-other.c", program.name)));
        }
        let built = reference.output().expect("run the reference compiler");
        assert!(
            built.status.success(),
            "the reference build of {} failed:\n{}",
            program.name,
            String::from_utf8_lossy(&built.stderr)
        );
        let expected = status_of(&theirs).expect("the reference run");
        if expected == observed {
            row.agreeing += 1;
        } else {
            row.disagreements
                .push((program.name.to_owned(), expected, observed));
        }
    }
    row.report("darwin-arm64");
    let _ = std::fs::remove_dir_all(&work);
    row.settle();
}

/// One batch run inside the container: GCC-14 builds and runs both sides.
const RUNNER: &str = r#"#!/bin/sh
cd /work || exit 2
for s in *.s; do
  base="${s%.s}"
  other=""
  if [ -f "$base-other.c" ]; then other="$base-other.c"; fi
  if ! gcc-14 -o "$base.mine" "$s" $other 2>"$base.link.err"; then
    echo "$base link $(head -c 300 "$base.link.err" | tr '\n' ' ')"
    continue
  fi
  ./"$base.mine" >/dev/null 2>&1
  mine=$?
  if ! gcc-14 -std=c11 -O0 -o "$base.theirs" "$base.c" $other 2>"$base.cc.err"; then
    echo "$base reference $(head -c 300 "$base.cc.err" | tr '\n' ' ')"
    continue
  fi
  ./"$base.theirs" >/dev/null 2>&1
  theirs=$?
  echo "$base run $mine $theirs"
done
"#;

/// The Linux lane: GCC-14 in the sealed container assembles, links and runs.
#[test]
fn the_frontier_corpus_agrees_with_gcc_in_the_sealed_container() {
    let image = match container() {
        Ok(image) => image,
        Err(reason) => {
            println!("skipped={reason}");
            return;
        }
    };
    let driver = match Driver::locate() {
        Ok(driver) => driver,
        Err(reason) => {
            println!("skipped={reason}");
            return;
        }
    };
    let _ = workspace();

    let work = std::env::temp_dir().join(format!("evocc-frontier-linux-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&work);
    std::fs::create_dir_all(&work).expect("a working directory");

    let mut row = Row::new();
    let mut expected_names = Vec::new();
    for program in PROGRAMS {
        let unit = materialize(&work, program, Target::Linux);
        match assembly(&driver, Target::Linux, &unit) {
            Ok(text) => {
                row.compiled += 1;
                std::fs::write(work.join(format!("{}.s", program.name)), text)
                    .expect("the emitted text");
                expected_names.push(program.name);
            }
            Err(reason) => {
                *row.refused.entry(reason).or_default() += 1;
            }
        }
    }

    let runner = work.join("runner.sh");
    std::fs::write(&runner, RUNNER).expect("the runner");
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        std::fs::set_permissions(&runner, std::fs::Permissions::from_mode(0o755))
            .expect("an executable runner");
    }

    let output = Command::new(CONTAINER_BIN)
        .arg("run")
        .arg("--rm")
        .arg("--platform")
        .arg("linux/arm64")
        .arg("--network")
        .arg("none")
        .arg("--volume")
        .arg(format!("{}:/work", work.display()))
        .arg(&image)
        .arg("/work/runner.sh")
        .output()
        .expect("run the sealed container");
    let stdout = String::from_utf8_lossy(&output.stdout).into_owned();
    assert!(
        output.status.success(),
        "the container run failed:\n{}\n{stdout}",
        String::from_utf8_lossy(&output.stderr)
    );

    for line in stdout.lines() {
        let mut fields = line.split_whitespace();
        let (Some(name), Some(kind)) = (fields.next(), fields.next()) else {
            continue;
        };
        match kind {
            "run" => {
                let mine: u8 = fields.next().and_then(|v| v.parse().ok()).unwrap_or(255);
                let theirs: u8 = fields.next().and_then(|v| v.parse().ok()).unwrap_or(255);
                row.ran += 1;
                if mine == theirs {
                    row.agreeing += 1;
                } else {
                    row.disagreements.push((name.to_owned(), theirs, mine));
                }
            }
            other => {
                *row.refused
                    .entry(format!("{other}: {}", fields.collect::<Vec<_>>().join(" ")))
                    .or_default() += 1;
            }
        }
    }

    row.report("linux-aarch64");
    let _ = std::fs::remove_dir_all(&work);
    row.settle();
}
